"""
Swarm Intelligence Co-Pilot Drawer.
Continuously audits the active dataset with heuristic diagnostic agents,
surfacing real-time optimization opportunities and 1-click repairs.
"""

from typing import List, Dict, Any, Optional
import pandas as pd
from PySide6.QtWidgets import (
    QWidget, QVBoxLayout, QHBoxLayout, QLabel, QFrame, QPushButton, QScrollArea
)
from PySide6.QtCore import Qt, Signal
from PySide6.QtGui import QFont


class SwarmCard(QFrame):
    """Tactile recommendation card generated by the swarm intelligence engine."""

    action_clicked = Signal(str, dict)  # (action_type, payload)

    def __init__(self, title: str, finding: str, severity: str, action_label: str, action_type: str, payload: dict, parent: Optional[QWidget] = None):
        super().__init__(parent)
        self.action_type = action_type
        self.payload = payload

        # Dynamic severity color styling
        if severity == "CRITICAL":
            bg_col = "#fef2f2"
            border_col = "#fecaca"
            badge_col = "#991b1b"
            badge_bg = "#fee2e2"
        elif severity == "WARNING":
            bg_col = "#fffbeb"
            border_col = "#fde68a"
            badge_col = "#92400e"
            badge_bg = "#fef3c7"
        else:
            bg_col = "#f0fdf4"
            border_col = "#bbf7d0"
            badge_col = "#166534"
            badge_bg = "#dcfce7"

        self.setStyleSheet(f"""
            QFrame {{
                background-color: {bg_col};
                border: 1px solid {border_col};
                border-radius: 8px;
                padding: 10px;
            }}
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        layout.setSpacing(6)

        header_row = QHBoxLayout()
        sev_label = QLabel(severity)
        sev_label.setFont(QFont("-apple-system, sans-serif", 8, QFont.Bold))
        sev_label.setStyleSheet(f"color: {badge_col}; background-color: {badge_bg}; padding: 2px 6px; border-radius: 4px;")
        header_row.addWidget(sev_label)

        title_label = QLabel(title)
        title_label.setFont(QFont("-apple-system, sans-serif", 11, QFont.Bold))
        title_label.setStyleSheet("color: #09090b;")
        header_row.addWidget(title_label)
        header_row.addStretch()

        layout.addLayout(header_row)

        desc = QLabel(finding)
        desc.setFont(QFont("-apple-system, sans-serif", 10))
        desc.setStyleSheet("color: #3f3f46; line-height: 1.3;")
        desc.setWordWrap(True)
        layout.addWidget(desc)

        btn = QPushButton(action_label)
        btn.setStyleSheet("""
            QPushButton {
                background-color: #ffffff;
                color: #09090b;
                border: 1px solid #d4d4d8;
                border-radius: 6px;
                padding: 4px 10px;
                font-size: 11px;
                font-weight: 600;
            }
            QPushButton:hover {
                background-color: #f4f4f5;
            }
        """)
        btn.clicked.connect(lambda: self.action_clicked.emit(self.action_type, self.payload))
        layout.addWidget(btn)


class SwarmDrawerWidget(QWidget):
    """Side drawer displaying autonomous swarm intelligence findings."""

    swarm_action_triggered = Signal(str, dict)

    def __init__(self, parent: Optional[QWidget] = None):
        super().__init__(parent)
        self._init_ui()

    def _init_ui(self):
        main_layout = QVBoxLayout(self)
        main_layout.setContentsMargins(12, 12, 12, 12)
        main_layout.setSpacing(10)

        header_row = QHBoxLayout()
        title = QLabel("Swarm Intelligence Co-Pilot")
        title.setFont(QFont("-apple-system, sans-serif", 13, QFont.Bold))
        title.setStyleSheet("color: #09090b;")
        header_row.addWidget(title)

        status_badge = QLabel("LIVE AUDIT")
        status_badge.setStyleSheet("color: #065f46; background-color: #d1fae5; font-size: 9px; font-weight: 700; padding: 2px 6px; border-radius: 4px;")
        header_row.addWidget(status_badge)
        header_row.addStretch()

        main_layout.addLayout(header_row)

        self.scroll_area = QScrollArea()
        self.scroll_area.setWidgetResizable(True)
        self.scroll_area.setStyleSheet("QScrollArea { border: none; background: transparent; }")

        self.cards_container = QWidget()
        self.cards_layout = QVBoxLayout(self.cards_container)
        self.cards_layout.setContentsMargins(0, 0, 0, 0)
        self.cards_layout.setSpacing(8)
        self.cards_layout.addStretch()

        self.scroll_area.setWidget(self.cards_container)
        main_layout.addWidget(self.scroll_area)

    def audit_dataset(self, df: pd.DataFrame):
        """Runs autonomous heuristics across dataframe."""
        # Clear existing cards
        for i in reversed(range(self.cards_layout.count())):
            item = self.cards_layout.itemAt(i)
            if item and item.widget():
                item.widget().setParent(None)

        if df.empty:
            no_data = QLabel("No active dataset loaded for swarm audit.")
            no_data.setStyleSheet("color: #71717a; font-size: 11px;")
            self.cards_layout.addWidget(no_data)
            self.cards_layout.addStretch()
            return

        findings = []

        # Heuristic 1: Margin Leak Check
        if "gross_margin" in df.columns:
            leaks = df[df["gross_margin"] < 0]
            if len(leaks) > 0:
                total_loss = abs(leaks["gross_margin"].sum())
                findings.append({
                    "title": "Margin Leakage Detected",
                    "finding": f"Found {len(leaks)} transactions with negative gross margin totaling ${total_loss:,.2f} in leaked profit.",
                    "severity": "CRITICAL",
                    "action_label": "Filter Negative Margins",
                    "action_type": "filter_margin_leaks",
                    "payload": {"query": "gross_margin >= 0"},
                })

        # Heuristic 2: Missing Values
        null_counts = df.isna().sum()
        high_nulls = null_counts[null_counts > 0]
        if not high_nulls.empty:
            worst_col = high_nulls.index[0]
            cnt = int(high_nulls.iloc[0])
            findings.append({
                "title": "Null Values in Key Column",
                "finding": f"Column '{worst_col}' contains {cnt} missing cells ({cnt/len(df):.1%}). Impute or drop to avoid modeling errors.",
                "severity": "WARNING",
                "action_label": "Drop Null Rows",
                "action_type": "drop_nulls",
                "payload": {"subset": [worst_col]},
            })

        # Heuristic 3: Duplicate Order Records
        id_col = next((c for c in ["order_id", "transaction_id", "customer_id"] if c in df.columns), None)
        if id_col and df[id_col].duplicated().any():
            dup_cnt = int(df[id_col].duplicated().sum())
            findings.append({
                "title": "Duplicate Record Keys",
                "finding": f"Found {dup_cnt} duplicate values in key column '{id_col}'. May cause double-counting in revenue rollups.",
                "severity": "WARNING",
                "action_label": "Deduplicate by Key",
                "action_type": "deduplicate",
                "payload": {"subset": [id_col]},
            })

        # Heuristic 4: Healthy Invariants
        if not findings:
            findings.append({
                "title": "100% Invariant Compliance",
                "finding": "Zero margin leaks, zero duplicates, and clean column distributions verified across all rows.",
                "severity": "INFO",
                "action_label": "Run Causal Elasticity",
                "action_type": "trigger_elasticity",
                "payload": {},
            })

        for f in findings:
            card = SwarmCard(
                title=f["title"],
                finding=f["finding"],
                severity=f["severity"],
                action_label=f["action_label"],
                action_type=f["action_type"],
                payload=f["payload"],
                parent=self
            )
            card.action_clicked.connect(self.swarm_action_triggered.emit)
            self.cards_layout.addWidget(card)

        self.cards_layout.addStretch()
